INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`, `setting_type`, `setting_group`, `setting_order`, `setting_options`, `description`, `created_at`, `updated_at`) VALUES ('28', 'about_story_text', 'Founded with the vision of providing safe, comfortable, and affordable accommodation for students, Student Boarding House has been a trusted home for hundreds of students pursuing their academic dreams. We understand the challenges students face when looking for the right place to stay while studying.', 'textarea', 'about', '53', NULL, 'About story text (use || for paragraphs)', '2026-07-15 17:11:27', '2026-07-26 14:47:52');
