INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`, `setting_type`, `setting_group`, `setting_order`, `setting_options`, `description`, `created_at`, `updated_at`) VALUES ('31', 'about_mission', 'To provide affordable, safe, and comfortable boarding house accommodations that support students in their academic journey. We strive to create a nurturing environment where students can thrive, build lasting friendships, and focus on their studies without the worry of their living arrangements.', 'textarea', 'about', '56', NULL, 'Mission statement', '2026-07-15 17:11:27', '2026-07-26 14:18:49');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`, `setting_type`, `setting_group`, `setting_order`, `setting_options`, `description`, `created_at`, `updated_at`) VALUES ('32', 'about_vision', 'To be the most trusted and preferred student dormitory, known for our commitment to quality service, student welfare, and community building. We envision a network of modern, well-maintained dormitories that set the standard for student living accommodations across the country.', 'textarea', 'about', '57', NULL, 'Vision statement', '2026-07-15 17:11:27', '2026-07-26 14:18:49');
